#!/bin/sh
# Generated by frostfire. The official Linux nginx image renders /etc/nginx/templates
# with envsubst at startup. This does the same on FreeBSD, then reloads every 6h so
# renewed certificates are picked up.
set -eu

out=/usr/local/etc/nginx/conf.d
mkdir -p "$out"
rm -f "$out"/*.conf
for t in /frostfire/templates/*.template; do
    [ -e "$t" ] || continue
    # Only ${DOMAIN} is replaced, so nginx's own $variables are left alone.
    envsubst '${DOMAIN}' < "$t" > "$out/$(basename "$t" .template)"
done

/usr/local/sbin/nginx -t -q
/usr/local/sbin/nginx -g 'daemon off;' &
pid=$!
trap 'kill -QUIT "$pid" 2>/dev/null' TERM INT
( while sleep 21600; do /usr/local/sbin/nginx -s reload; done ) &

set +e
wait "$pid"
status=$?
if kill -0 "$pid" 2>/dev/null; then
    wait "$pid"
    status=$?
fi
exit "$status"
